/// <summary>
/// EXPERIMENTAL: Agent APIs are likely to change.
///
/// How a message landed in an agent&apos;s evaluation.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter<AgentMessageDelivery>))]
public enum AgentMessageDelivery
{
    /// <summary>
    /// The message opened a new turn: the agent was idle or newly started.
    /// </summary>
    STARTED,
    /// <summary>
    /// The message was absorbed into the in-flight turn at a step boundary, steering it.
    /// </summary>
    STEERED,
    /// <summary>
