/// <summary>
/// Why a source commit cannot be pulled.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter<WorkspaceCommitPickReason>))]
public enum WorkspaceCommitPickReason
{
    /// <summary>
    /// No conflict.
    /// </summary>
    NONE,
    /// <summary>
    /// The patch conflicts with committed content.
    /// </summary>
    CONTENT,
    /// <summary>
    /// The commit touches uncommitted paths in the receiving workspace.
    /// </summary>
    DIRTY
}

/// <summary>
/// Whether a source commit can be pulled.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter<WorkspaceCommitPickStatus>))]
public enum WorkspaceCommitPickStatus
{
    /// <summary>
    /// The commit can be applied.
    /// </summary>
    PICKABLE,
    /// <summary>
    /// The commit is already present by hash or cherry-pick origin.
    /// </summary>
    PICKED,
    /// <summary>
    /// The patch is already present, or applying it would be empty.
    /// </summary>
    REDUNDANT,
    /// <summary>
    /// The commit cannot be applied; see reason and conflictPaths.
    /// </summary>
    CONFLICT
}

